INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 2, 5, 'go',
  'Driest stretch. 23-30C. Sand-track at firmest. Pamban photography clearest.',
  'February is the technical peak. Rainfall under 20mm, sand track at firmest, 4WD-jeep service at full reliability. Daytime 27-30C, trade winds steady. Pamban new vertical-lift bridge photography at year-cleanest.',
  NULL,
  'February in Dhanushkodi is the dry-quarter technical peak. Rainfall under 20mm, daytime 27-30C, nights 23-24C, humidity 65 percent, trade winds steady. The 8km Arichalmunai-tip sand track at year-firmest — 4WD-jeep service runs at full reliability, ₹150-250 per seat shared aggregator, 90-minute round trip including 30-minute stop at the ruins. The Kothandaramaswamy Temple (the 1964 cyclone survivor halfway between Arichalmunai and the tip) at quietest mid-month visitor load. The ghost-town ruins — the church foundation, post office wall, railway platform stones, lighthouse remnant — walkable through full afternoon. The point where the Bay of Bengal meets the Indian Ocean is visible from a 200m walk past the ruins; the wave-collision line is sharpest at low tide (the new Pamban Bridge''s tide chart at the Mandapam station is the reference). Adam''s Bridge (the chain of limestone shoals extending toward Talaimannar Sri Lanka, ~30km) visible from the tip on clear days as a pale line on the southeast horizon — boat-trips to the shoals are not commercially operational for tourists.'
)
