INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 3, 4, 'go',
  'Last cool month. 25-32C. Sand track firm. Trip works through afternoon for first half.',
  'March extends February''s pattern. Daytime 30-32C, sand track firm, 4WD service unchanged. Trip works through full afternoon for the first half; last fortnight pushes the tip walk past comfort 11am-3pm. Start by 7am.',
  NULL,
  'March in Dhanushkodi is the transition month. Daytime 30-32C, nights 25-26C, humidity 70 percent, rainfall under 30mm. The 8km Arichalmunai-tip sand track at firm-and-dry; the 4WD-jeep service runs unchanged at ₹150-250 per seat. The Kothandaramaswamy Temple at the halfway mark at full access. The ghost-town ruins at the tip — church foundation, post office wall, railway platform stones — walkable through full afternoon for the first half of the month. By the third week, daytime climbs past 32C and the tip-walk pushes past comfort 11am-3pm; start trips by 7am from Rameswaram (18km, 25 minutes to Arichalmunai). The wave-collision point where the Bay meets the Indian Ocean visible at low tide. Trade winds steady through both shifts; visibility 12-18km on clear afternoons. Stay in Rameswaram — Daiwik Hotels ₹2,500-4k, Hyatt Place ₹3,500-5k, beach homestays ₹800-1,500. Pamban Bridge photography on the drive at year-cleanest before pre-monsoon haze settles in. No tourism infrastructure past Arichalmunai — pack water (1.5L per person), hat, sun cover. The next clean window after April is October.'
)
