INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 4, 3, 'wait',
  'Pre-monsoon heat. 27-35C. Tip-walk endurance-mode. Sand track holding. Start at dawn.',
  'April pushes Dhanushkodi past comfort. Daytime 33-35C, no shade on the 8km sand track or at the tip ruins. Trip workable only as a 6-9am window. AC retreat in Rameswaram noon onward.',
  'April at Dhanushkodi pushes the ghost-town visit into endurance. The 8km sand track has zero shade; the tip ruins have zero shade. The trip works only as a 6-9am sprint. Wait for October when the trip returns to normal-comfort range.',
  'April in Dhanushkodi is the pre-monsoon contraction. Daytime 33-35C, nights 27-28C, humidity 75 percent, rainfall under 30mm. The 8km Arichalmunai-tip sand track is dry and firm; the 4WD-jeep service runs at ₹150-250 per seat but operators caution against post-9am trips. There is zero shade on the entire 8km track and zero shade at the ghost-town ruins at the tip. Walking past the church foundation and post office wall at noon means 35-38C surface heat with no respite. The Kothandaramaswamy Temple at the halfway mark provides 15-20 minutes of partial shade. The wave-collision point where the Bay meets the Indian Ocean still workable at low tide. Operators run the trip 6am-9am as a sprint visit; full-day trips not advisable. Stay in Rameswaram — Daiwik Hotels ₹2,000-3,500, Hyatt Place ₹3-4,500, beach homestays ₹700-1,200. Pamban Bridge photography limited to dawn / last-light slots. International visitor load near-zero; domestic Char Dham circuits skip the Dhanushkodi extension in April. October opens the proper return window.'
)
