INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 5, 2, 'wait',
  'Heat peak. 28-37C. Tip-walk impossible mid-day. Trade winds irregular.',
  'May at Dhanushkodi is endurance-only. Daytime 35-37C, sand-track surface 50-55C at noon, no shade. Trip works only as a 5:30-8am sprint and requires extra water. Push to October.',
  'May pushes Dhanushkodi to the limit. The ghost-town tip-walk is barefoot-impossible. The 4WD service still runs but operators won''t go past 9am. Wait for October when the Bay-storm season ends and the sand track is back to safe.',
  'May in Dhanushkodi is the heat peak. Daytime 35-37C, nights 28-29C, humidity 75 percent, rainfall under 40mm. The Bay trade winds become irregular; some afternoons the wind drops entirely and the 8km Arichalmunai-tip sand track surface hits 50-55C. The 4WD-jeep service still runs at ₹150-250 per seat but operators won''t go past 9am from the Arichalmunai aggregator desk — they don''t want to be stuck mid-track in the afternoon heat. The ghost-town ruins at the tip are walkable only with shoes, water (2L per person mandatory), and a 5:30-8am sprint window. The Kothandaramaswamy Temple at the halfway mark offers brief shade respite. The wave-collision point at the absolute tip still visible at low tide; check the Mandapam tide chart at the new Pamban Bridge station. Adam''s Bridge horizon line still visible on clear dawns. Stay in Rameswaram — Daiwik Hotels ₹1,800-3k, Hyatt Place ₹2,500-4k, beach homestays ₹600-1,000. The Bay-storm season starts in late June, knocking the sand track out of operation for the next four months. October is the proper return window.'
)
