INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 6, 2, 'wait',
  'SW monsoon spillover. 27-34C. Sand track wets up. 4WD service starts conditional.',
  'June brings 60-80mm rainfall as SW monsoon spillover reaches the eastern coast. Sand track wets up, 4WD service runs but with conditional go/no-go. Trade winds return. Daytime eases to 32-34C. Still wait for October.',
  'June at Dhanushkodi sees the sand-track conditions degrade. SW monsoon spillover wets the 8km track; 4WD operators run conditional services. The Bay-storm season begins in July. Wait for October.',
  'June in Dhanushkodi is the first easing month of the heat dome and the start of the wet season. Southwest monsoon spillover delivers 60-80mm rainfall across 8-10 wet days, mostly late-afternoon thunderstorms. Daytime 32-34C, nights 27-28C, humidity 80 percent, Bay trade winds return to standard pattern. The 8km Arichalmunai-tip sand track starts wetting up — the 4WD-jeep service runs conditional go/no-go through the month, with the operators at the Arichalmunai aggregator desk calling each morning based on overnight rainfall. The Kothandaramaswamy Temple at the halfway mark stays accessible. The ghost-town ruins at the tip walkable on dry mornings — but visitor load is the lowest of the dry quarter. The wave-collision point at the absolute tip visible on clear days; sea state climbing through the month. Adam''s Bridge horizon line obscured by spray on windy days. Stay in Rameswaram — Daiwik Hotels ₹2,000-3,500, Hyatt Place ₹3-4,500, beach homestays ₹700-1,200. The Bay-storm season starts mid-July; the next four months will see frequent track closures. October opens the proper return window after the Bay calms.'
)
