INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 8, 1, 'skip',
  'Continued Bay storms. 27-33C. 4WD suspends 3-5 days/week. Skip.',
  NULL,
  'August continues July''s pattern. Bay storms, sustained wind, sand-track flooding. 4WD-jeep service runs 15-20 days out of 31. The tip-walk + ruins + wave-collision combination — the whole reason to come — runs at 30 percent. Skip.',
  'August in Dhanushkodi continues the Bay-storm pattern. Rainfall 100-130mm across 13-15 wet days, daytime 31-33C, nights 27-28C, humidity 85 percent. The Bay-side wind sustains through most afternoons; the 8km Arichalmunai-tip sand track floods on heavy-rain days. 4WD-jeep service from the Arichalmunai aggregator desk runs 15-20 days out of 31; operators post daily go/no-go calls at 7am based on overnight rain and morning wind reading. The Kothandaramaswamy Temple at the halfway mark accessible by road on dry mornings. The ghost-town ruins at the tip visible from the road end; the 200m walk to the wave-collision point closed during storm conditions. Adam''s Bridge horizon line obscured by spray and cloud most days. The trip-defining tip-visit runs at 30-40 percent reliability. Stay in Rameswaram if at all — Daiwik Hotels ₹1,800-3k, Hyatt Place ₹2,500-4k, beach homestays ₹500-900. The brief explicitly flags Jul-Sep as the avoid window; October opens the proper return window after the Bay calms.'
)
