INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 9, 1, 'skip',
  'Storm tail. 27-32C. 4WD unreliable. Push to mid-Oct.',
  NULL,
  'September is the storm-tail month. Bay wind eases through the third week but the 4WD axis to Dhanushkodi remains unreliable. Hotel rates at off-season. The trip runs at 40-50 percent. Push to mid-Oct for the proper window.',
  'September in Dhanushkodi is the Bay-storm tail. Rainfall remains at 90-110mm across 11-13 wet days, daytime 30-32C, nights 27C, humidity 82 percent. Bay-side wind eases through the third week as the southwest monsoon retreats from the wider sub-continent (formal withdrawal around September 25-30). The 8km Arichalmunai-tip sand track conditions improve as overnight rainfall reduces; the 4WD-jeep service from the aggregator desk runs conditional go/no-go through the first half, with reliability climbing through the back half. The Kothandaramaswamy Temple accessible by road most mornings. The ghost-town ruins at the tip visible from the road end; the 200m walk to the wave-collision point opens on clear afternoons. Adam''s Bridge horizon line returns to visibility on the last week''s clear dawns. The trip-defining tip-visit runs at 50-60 percent reliability through the month. Stay in Rameswaram — Daiwik Hotels ₹2,000-3,500, Hyatt Place ₹3-4,500, beach homestays ₹600-1,000. The October 15 onward window — Bay calmed, sand track firmed, full 4WD service — is dramatically better. Skip unless on a locked-itinerary Char Dham circuit with rain-day flexibility.'
)
