INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('dhanushkodi', 10, 4, 'go',
  'NE monsoon arrives mid-Oct. 25-31C. 4WD reliable second half. Cyclone watch active.',
  'October is the season-opener. First half still volatile; from Oct 15 the sand track firms and 4WD reliability returns. NE monsoon active as evening showers. Cyclone watch (Gaja Nov 2018 hit Nagapattinam) — check IMD before locking dates.',
  NULL,
  'October in Dhanushkodi is the proper return month. The southwest monsoon withdraws around October 1; the northeast monsoon — Tamil Nadu''s actual rain season — arrives around October 15 as late-afternoon and evening showers (not the all-day Bay storms of Jul-Sep). Rainfall 200-250mm across 10-12 wet days. Daytime 28-31C, nights 25-26C, humidity 78 percent, Bay trade winds stable from 9am through 7pm. The 8km Arichalmunai-tip sand track firms up through the back half — sand drainage post-storm is faster than the SW-monsoon spillover wets. The 4WD-jeep service from the aggregator desk returns to full reliability from October 15, ₹150-250 per seat. The Kothandaramaswamy Temple at the halfway mark, the ghost-town ruins at the tip, the 200m walk to the wave-collision point where the Bay meets the Indian Ocean — all return to full access. Adam''s Bridge horizon line visible on clear dawns. Stay in Rameswaram — Daiwik Hotels ₹2,800-4k, Hyatt Place ₹3,500-5k, beach homestays ₹900-1,500. **Cyclone watch active:** the Bay generates Oct-Dec cyclones (Gaja Nov 2018 hit Nagapattinam 150km north, Nivar Nov 2020 hit Cuddalore further north).'
)
